{
  "summary": "Proposing a compact quality set for a blank format-2 story: dramatic tension, protagonist agency, relationship warmth, and a story-phase enum to steer beats. All are extractor-sourced with read_as where the answer is directly visible in prose.",
  "ops": [
    {
      "kind": "addQuality",
      "quality": {
        "key": "tension",
        "type": "int",
        "source": "extractor",
        "rubric": "On a 0-10 scale, how much unresolved dramatic pressure is present in this passage (0 = calm, 10 = peak crisis)?",
        "read_as": "rating"
      }
    },
    {
      "kind": "addQuality",
      "quality": {
        "key": "protagonist_agency",
        "type": "int",
        "source": "extractor",
        "rubric": "On a 0-10 scale, how much is the protagonist actively driving events rather than reacting to them (0 = purely reactive, 10 = fully in control)?",
        "read_as": "rating"
      }
    },
    {
      "kind": "addQuality",
      "quality": {
        "key": "bond_strength",
        "type": "int",
        "source": "extractor",
        "rubric": "On a 0-10 scale, how strong is the emotional bond between the protagonist and their closest ally in this passage (0 = estranged, 10 = inseparable)?",
        "read_as": "rating"
      }
    },
    {
      "kind": "addQuality",
      "quality": {
        "key": "story_phase",
        "type": "enum",
        "source": "extractor",
        "rubric": "Which story phase does this passage belong to: setup, rising, crisis, or resolution?",
        "values": ["setup", "rising", "crisis", "resolution"],
        "read_as": "choice"
      }
    }
  ]
}

{
  "summary": "Declared the core dramatic-state qualities for the story: tension (scene pressure), protagonist_agency (how much the lead drives events), bond_strength (closeness with the key ally), and two boolean flags for irreversible turns and open secrets. All are extractor-sourced with readable rubrics so a judge can score them each turn.",
  "ops": [
    {
      "kind": "addQuality",
      "quality": {
        "key": "tension",
        "type": "int",
        "source": "extractor",
        "read_as": "rating",
        "rubric": "from 1 (calm, low stakes, nothing pressing) to 5 (peak crisis, immediate threat or irreversible confrontation)",
        "criteria": {
          "levels": [
            { "value": 1, "label": "calm", "description": "Scene is relaxed; no immediate threat or pressure." },
            { "value": 2, "label": "stirring", "description": "Unease or friction is present but not yet dangerous." },
            { "value": 3, "label": "tense", "description": "Clear conflict or risk; characters are on edge." },
            { "value": 4, "label": "critical", "description": "High stakes with real consequences looming this scene." },
            { "value": 5, "label": "peak", "description": "Crisis point; violence, betrayal, or a point of no return." }
          ]
        }
      }
    },
    {
      "kind": "addQuality",
      "quality": {
        "key": "protagonist_agency",
        "type": "int",
        "source": "extractor",
        "read_as": "rating",
        "rubric": "from 1 (protagonist is passive, reacting to others) to 5 (protagonist actively drives the scene's outcome)",
        "criteria": {
          "levels": [
            { "value": 1, "label": "passive", "description": "Protagonist only reacts; others set the agenda." },
            { "value": 2, "label": "reactive", "description": "Protagonist responds but makes no real choices." },
            { "value": 3, "label": "engaged", "description": "Protagonist makes at least one meaningful choice." },
            { "value": 4, "label": "driving", "description": "Protagonist's decisions shape the scene's direction." },
            { "value": 5, "label": "commanding", "description": "Protagonist dictates the scene's outcome." }
          ]
        }
      }
    },
    {
      "kind": "addQuality",
      "quality": {
        "key": "bond_strength",
        "type": "int",
        "source": "extractor",
        "read_as": "rating",
        "rubric": "from 1 (distant or hostile) to 5 (deep trust and intimacy) between the protagonist and their key ally",
        "criteria": {
          "levels": [
            { "value": 1, "label": "distant", "description": "Cold, wary, or openly hostile." },
            { "value": 2, "label": "guarded", "description": "Polite but walls up; little trust." },
            { "value": 3, "label": "warming", "description": "Growing rapport; some trust shown." },
            { "value": 4, "label": "close", "description": "Real trust; willing to take risks for each other." },
            { "value": 5, "label": "bonded", "description": "Deep intimacy; unshakable loyalty." }
          ]
        }
      }
    },
    {
      "kind": "addQuality",
      "quality": {
        "key": "point_of_no_return",
        "type": "bool",
        "source": "extractor",
        "read_as": "choice",
        "rubric": "Has an irreversible choice or event occurred that cannot be undone in this story?"
      }
    },
    {
      "kind": "addQuality",
      "quality": {
        "key": "secret_exposed",
        "type": "bool",
        "source": "extractor",
        "read_as": "choice",
        "rubric": "Has a significant secret been revealed to a character who did not know it?"
      }
    }
  ]
}

